CREATE TABLE organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE memberships(org_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('org_admin','project_manager','pmo','contributor','reader')),PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),org_id TEXT NOT NULL,expires_at INTEGER NOT NULL,FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE projects(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',owner_id TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','completed')),budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(budget_cents>=0),color TEXT NOT NULL DEFAULT 'sage',created_at TEXT NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,owner_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE project_members(org_id TEXT NOT NULL,project_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(project_id,user_id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE tasks(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',assignee_id TEXT,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','review','done')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),milestone INTEGER NOT NULL DEFAULT 0 CHECK(milestone IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(org_id,project_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,assignee_id) REFERENCES memberships(org_id,user_id),CHECK(end_date>=start_date));
CREATE TABLE documents(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(org_id,project_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE document_versions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,document_id TEXT NOT NULL,version INTEGER NOT NULL,storage_key TEXT NOT NULL UNIQUE,size INTEGER NOT NULL,sha256 TEXT NOT NULL,uploaded_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(document_id,version),FOREIGN KEY(org_id,project_id,document_id) REFERENCES documents(org_id,project_id,id),FOREIGN KEY(org_id,uploaded_by) REFERENCES memberships(org_id,user_id));
CREATE TABLE activity(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,actor_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE invitations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('project_manager','pmo','contributor','reader')),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX task_project ON tasks(org_id,project_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX activity_project ON activity(org_id,project_id,created_at);
